class Solution {
    struct Node {
        int next[26],link=0,terminal=INT_MAX;
        Node() {fill(next,next+26,-1);}
    };
public:
    int minimumCost(string target,vector<string>& words,vector<int>& costs) {
        vector<Node> trie(1);
        for(int i=0;i<(int)words.size();++i) {
            int u=0;
            for(char ch:words[i]) {
                int c=ch-'a';
                if(trie[u].next[c]==-1) {
                    int id=trie.size();trie[u].next[c]=id;
                    trie.emplace_back();
                }
                u=trie[u].next[c];
            }
            trie[u].terminal=min(trie[u].terminal,costs[i]);
        }
        // Failure links and output links permit DP updates only on matching words.
        vector<int> out(trie.size(),-1),depth(trie.size());
        queue<int> q;
        for(int c=0;c<26;++c) {
            int v=trie[0].next[c];
            if(v==-1) trie[0].next[c]=0;
            else {trie[v].link=0;depth[v]=1;q.push(v);}
        }
        while(!q.empty()) {
            int u=q.front();q.pop();
            int f=trie[u].link;
            out[u]=(trie[f].terminal!=INT_MAX?f:out[f]);
            for(int c=0;c<26;++c) {
                int v=trie[u].next[c];
                if(v==-1) trie[u].next[c]=trie[f].next[c];
                else {trie[v].link=trie[f].next[c];depth[v]=depth[u]+1;q.push(v);}
            }
        }
        const int INF=1000000000;
        vector<int> dp(target.size()+1,INF);dp[0]=0;
        int state=0;
        for(int i=0;i<(int)target.size();++i) {
            state=trie[state].next[target[i]-'a'];
            for(int u=state;u!=-1;u=out[u]) {
                if(trie[u].terminal==INT_MAX) continue;
                int len=depth[u];
                if(dp[i+1-len]!=INF)
                    dp[i+1]=min(dp[i+1],dp[i+1-len]+trie[u].terminal);
            }
        }
        return dp.back()==INF?-1:dp.back();
    }
};
